<script setup lang="ts">
import { computed } from 'vue'
import AppShell from '../../components/AppShell.vue'
import Icon from '../../components/Icon.vue'
import ThermoArt from '../../components/ThermoArt.vue'
import ResourceCard from '../../components/ResourceCard.vue'
import { chapters, nodes, resources, resourceTypeLabel } from '../../data/course'
import { navigate, stats, progress, openResource, learnedNodeIds } from '../../store'
const courseChapters = computed(() => ['ch1', 'ch2', 'ch5'].map(id => chapters.find(c => c.id === id)).filter(Boolean))
const featured = computed(() => resources.filter(r => r.type === 'video').slice(0, 3))
const resume = computed(() => resources.find(r => r.id === progress.lastResource) || resources.find(r => r.type === 'video'))
const date = new Date().toLocaleDateString('zh-CN', { month: 'long', day: 'numeric', weekday: 'long' })
function chapterProgress(id: string) { const ns = nodes.filter(n => n.chapterId === id); return ns.length ? Math.round(ns.filter(n => learnedNodeIds.value.includes(n.id)).length / ns.length * 100) : 0 }
</script>
<template><AppShell active="index" title="学习首页">
  <div class="page-heading"><div><h1>每一次探索，都离理解更近一步<span class="heading-period">.</span></h1><p>欢迎来到热知，开启今天的工程热力学学习之旅。</p></div><div class="home-date"><Icon name="clock" :size="14" />{{ date }}</div></div>
