    <section class="continue-panel panel"><div class="continue-top"><span class="section-kicker">YOUR LEARNING JOURNEY</span><Icon name="book" :size="18" /></div><h3>{{ progress.lastResource ? '接着上次，继续探索' : '从这里，开始第一课' }}</h3><p>把今天的小进步，连成明天的大收获。</p><div class="resume-line"><span class="resume-icon"><Icon name="play" :size="18" /></span><div><span>{{ resume ? resourceTypeLabel[resume.type] : '知识课件' }}</span><strong>{{ resume?.title || '热力学第一定律' }}</strong></div></div><div class="continue-progress"><span>课程知识点学习进度</span><strong>{{ stats.progress }}%</strong></div><div class="progress-track"><span :style="{ width: stats.progress + '%' }"></span></div><button class="button primary full-width" @click="resume && openResource(resume.id)">{{ progress.lastResource ? '继续学习' : '开始学习' }}<Icon name="arrow" :size="16" /></button></section></div>
  <div class="stats-grid"><article class="stat-card"><span class="stat-icon"><Icon name="graph" :size="21" /></span><div><span class="stat-label">已学知识点</span><div class="count-number">{{ stats.learned }}<small>/ {{ nodes.length }}</small></div></div><span class="stat-caption">每一个连接都有意义</span></article><article class="stat-card"><span class="stat-icon blue"><Icon name="video" :size="21" /></span><div><span class="stat-label">已学资源</span><div class="count-number">{{ stats.completed }}<small>/ {{ resources.length }}</small></div></div><span class="stat-caption">理解，从这里发生</span></article><article class="stat-card"><span class="stat-icon orange"><Icon name="edit" :size="21" /></span><div><span class="stat-label">累计练习</span><div class="count-number">{{ stats.attempts }}<small>次</small></div></div><span class="stat-caption">让知识经得起检验</span></article><article class="stat-card"><span class="stat-icon purple"><Icon name="target" :size="21" /></span><div><span class="stat-label">练习正确率</span><div class="count-number">{{ stats.attempts ? stats.accuracy : '—' }}<small v-if="stats.attempts">%</small></div></div><span class="stat-caption">{{ stats.attempts ? '基于你的实际作答' : '完成首次练习后生成' }}</span></article></div>
